import { BaseLitElement, webComponent } from '@domg-wc/common';
import { CSSResult, html, TemplateResult } from 'lit';
import { vlButtonStyles } from '../button-style/vl-button-style.css';

@webComponent('my-component-with-button')
export class MyComponentWithButton extends BaseLitElement {
    static get styles(): CSSResult[] {
        return [vlButtonStyles('button', '.my-button')];
    }

    render(): TemplateResult {
        return html`
            <button class="my-button">My styled button</button>
        `
    }
}

import { BaseLitElement, webComponent } from '@domg-wc/common';
import { CSSResult, html, TemplateResult } from 'lit';
import { vlButtonStyles } from '../button-style/vl-button-style.css';

// Zoals het voorbeeld op de pagina, maar voor een link: vlButtonStyles('a', selector) geeft een <a> de opmaak van
// een knop.
@webComponent('my-component-with-link-button')
export class MyComponentWithLinkButton extends BaseLitElement {
    static get styles(): CSSResult[] {
        return [vlButtonStyles('a', '.my-button')];
    }

    render(): TemplateResult {
        return html`
            <a href="#" class="my-button">Klik hier</a>
        `;
    }
}
